@once
@push('styles')
<style>
    .ttw{--ttw-ink:#173246;--ttw-muted:#687c89;--ttw-line:#dce6eb;--ttw-blue:#176b87;--ttw-green:#14735a;--ttw-gold:#e9b949;display:grid;gap:16px;padding-bottom:32px;color:var(--ttw-ink)}
    .ttw a{text-underline-offset:2px}.ttw-hero{position:relative;overflow:hidden;display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:24px;padding:25px 27px;border-radius:16px;background:linear-gradient(122deg,#102d40,#155e75 62%,#14735a);color:#fff;box-shadow:0 15px 34px rgba(18,55,74,.17)}.ttw-hero:after{position:absolute;right:-72px;bottom:-105px;width:250px;height:250px;border:38px solid rgba(255,255,255,.055);border-radius:50%;content:""}.ttw-kicker{color:#bfe7e0;font-size:10px;font-weight:900;letter-spacing:.095em;text-transform:uppercase}.ttw-hero h1{position:relative;z-index:1;margin:5px 0 8px;color:#fff;font-size:clamp(1.45rem,2.7vw,2.15rem);font-weight:900}.ttw-hero p{position:relative;z-index:1;max-width:770px;margin:0;color:#d9eaf0;font-size:12px;line-height:1.6}.ttw-hero-actions{position:relative;z-index:1;display:flex;flex-wrap:wrap;gap:8px}
    .ttw-btn{display:inline-flex;min-height:38px;align-items:center;justify-content:center;gap:7px;padding:8px 13px;border:1px solid #cbd9df;border-radius:8px;background:#fff;color:#254555;font-size:10px;font-weight:900;text-decoration:none;cursor:pointer}.ttw-btn:hover{border-color:#77a9b7;color:#0d6077}.ttw-btn.primary{border-color:#0f766e;background:#0f766e;color:#fff}.ttw-btn.light{border-color:rgba(255,255,255,.3);background:rgba(255,255,255,.12);color:#fff}.ttw-btn.warn{border-color:#ebbd78;background:#fff8e9;color:#8b5215}.ttw-btn.danger{border-color:#e9b4b4;background:#fff8f8;color:#9b3434}.ttw-btn:disabled{cursor:not-allowed;filter:grayscale(.45);opacity:.55}
    .ttw-alert{display:flex;align-items:flex-start;gap:10px;padding:12px 14px;border:1px solid #b8ddcf;border-radius:10px;background:#effaf5;color:#24624d;font-size:11px}.ttw-alert.danger{border-color:#f0c0b8;background:#fff5f2;color:#8d3f32}.ttw-alert i{margin-top:2px}.ttw-alert strong{display:block;margin-bottom:2px}.ttw-alert p{margin:0}
    .ttw-metrics{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:9px}.ttw-metric{position:relative;overflow:hidden;padding:15px;border:1px solid var(--ttw-line);border-radius:12px;background:#fff;box-shadow:0 4px 14px rgba(19,51,68,.035)}.ttw-metric:before{position:absolute;top:0;right:0;left:0;height:3px;background:#d7e4e9;content:""}.ttw-metric.review:before{background:#3182a0}.ttw-metric.bank:before{background:#e0a832}.ttw-metric.ready:before{background:#1a8a62}.ttw-metric.action:before{background:#d16950}.ttw-metric i{color:#26768e}.ttw-metric strong{display:block;margin:8px 0 2px;font-size:21px;font-weight:900}.ttw-metric span{color:var(--ttw-muted);font-size:9px;font-weight:800;line-height:1.35}.ttw-value-strip{display:flex;align-items:center;gap:10px;padding:11px 14px;border:1px solid #d8e7e0;border-radius:10px;background:#f5faf8;color:#4e6a5f;font-size:10px}.ttw-value-strip i{display:grid;width:28px;height:28px;place-items:center;border-radius:8px;background:#dff2e9;color:#16704f}.ttw-value-strip strong{color:#23483b}
    .ttw-filter-shell,.ttw-panel{overflow:hidden;border:1px solid var(--ttw-line);border-radius:14px;background:#fff;box-shadow:0 6px 20px rgba(19,51,68,.04)}.ttw-panel-head,.ttw-filter-head{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;padding:16px 18px}.ttw-panel-head h2,.ttw-filter-head h2{margin:3px 0 0;font-size:16px;font-weight:900}.ttw-panel-head p,.ttw-filter-head p{margin:4px 0 0;color:var(--ttw-muted);font-size:10px}.ttw-section-kicker{color:#0f766e;font-size:8px;font-weight:900;letter-spacing:.085em;text-transform:uppercase}.ttw-clear{display:inline-flex;align-items:center;gap:5px;color:#955141;font-size:9px;font-weight:850;text-decoration:none}.ttw-filters{display:grid;grid-template-columns:minmax(210px,1.25fr) repeat(3,minmax(135px,.72fr));gap:9px;padding:14px 18px;border-top:1px solid #edf2f4;background:#f8fafb}.ttw-filters label,.ttw-label{display:block;margin-bottom:4px;color:#687d88;font-size:8px;font-weight:900;letter-spacing:.035em;text-transform:uppercase}.ttw-input{width:100%;min-height:38px;padding:8px 10px;border:1px solid #ccd9df;border-radius:8px;background:#fff;color:#243f4c;font-size:10px}.ttw-input:focus{border-color:#4089a0;box-shadow:0 0 0 3px rgba(23,107,135,.1);outline:0}.ttw-filter-actions{display:flex;grid-column:1/-1;justify-content:flex-end;gap:8px}
    .ttw-table-wrap{overflow:auto;border-top:1px solid #edf2f4}.ttw-table{width:100%;min-width:1120px;border-collapse:separate;border-spacing:0}.ttw-table th{padding:10px 12px;background:#17384f;color:#eef5f7;font-size:8px;font-weight:900;letter-spacing:.055em;text-align:left;text-transform:uppercase}.ttw-table td{padding:13px 12px;border-bottom:1px solid #e8eef1;color:#405865;font-size:10px;line-height:1.45;vertical-align:middle}.ttw-table tbody tr:nth-child(even) td{background:#fbfcfd}.ttw-table tbody tr:hover td{background:#f2f8fa}.ttw-org strong,.ttw-item-name strong{display:block;color:#193b4c;font-size:10px;font-weight:900}.ttw-org small,.ttw-item-name small,.ttw-plan small{display:block;margin-top:3px;color:#7a8d97;font-size:8px}.ttw-code{color:#0f766e;font-size:8px;font-weight:900;letter-spacing:.025em}.ttw-money{text-align:right;white-space:nowrap}.ttw-money strong{color:#163c50;font-size:11px}.ttw-doc-summary{display:grid;gap:4px}.ttw-doc-summary span{display:inline-flex;align-items:center;gap:5px;color:#627985;font-size:8px}.ttw-status{display:inline-flex;align-items:center;gap:5px;padding:5px 8px;border-radius:999px;background:#eef2f4;color:#536974;font-size:8px;font-weight:900;text-transform:uppercase}.ttw-status.submitted{background:#e7f2fb;color:#276681}.ttw-status.approved{background:#fff4d8;color:#8a5a10}.ttw-status.no_objection_obtained,.ttw-status.published{background:#e5f6ed;color:#216c4a}.ttw-status.revision_requested,.ttw-status.rejected{background:#fff0e9;color:#9a462f}.ttw-next{display:block;margin-top:5px;color:#788991;font-size:8px;line-height:1.35}.ttw-empty{padding:42px 20px;text-align:center}.ttw-empty i{display:grid;width:50px;height:50px;margin:0 auto 10px;place-items:center;border-radius:15px;background:#edf5f7;color:#27728a;font-size:20px}.ttw-empty h3{margin:0;font-size:14px}.ttw-empty p{margin:5px 0;color:var(--ttw-muted);font-size:10px}.ttw-pagination{padding:13px 18px}
    .ttw-breadcrumb{display:flex;align-items:center;gap:7px;color:#72858f;font-size:9px}.ttw-breadcrumb a{color:#176b87;font-weight:850;text-decoration:none}.ttw-record-hero{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:start;gap:20px;padding:20px 22px;border:1px solid var(--ttw-line);border-radius:14px;background:linear-gradient(135deg,#fff,#f4f9fa)}.ttw-record-hero h1{margin:4px 0 7px;color:#18394a;font-size:clamp(1.25rem,2.3vw,1.8rem);font-weight:900}.ttw-record-meta{display:flex;flex-wrap:wrap;gap:6px 13px;color:#6f838e;font-size:9px}.ttw-record-meta span{display:inline-flex;align-items:center;gap:5px}.ttw-record-actions{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:7px}
    .ttw-flow{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));padding:13px;border:1px solid var(--ttw-line);border-radius:12px;background:#fff}.ttw-flow-step{position:relative;display:grid;grid-template-columns:27px minmax(0,1fr);align-items:center;gap:7px;padding:5px 11px}.ttw-flow-step:not(:last-child):after{position:absolute;right:-1px;width:1px;height:28px;background:#dfe7eb;content:""}.ttw-flow-step>span{display:grid;width:27px;height:27px;place-items:center;border-radius:50%;background:#edf2f4;color:#7c8d95;font-size:9px;font-weight:900}.ttw-flow-step strong{display:block;font-size:8px}.ttw-flow-step small{display:block;margin-top:2px;color:#7c8e97;font-size:7px;line-height:1.25}.ttw-flow-step.complete>span{background:#dff2e9;color:#176a4d}.ttw-flow-step.current>span{background:#176b87;color:#fff;box-shadow:0 0 0 4px #e2f1f5}.ttw-flow-step.attention>span{background:#fff0e7;color:#a24a2f}
    .ttw-workspace{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(310px,.8fr);align-items:start;gap:14px}.ttw-panel-body{padding:17px 18px;border-top:1px solid #edf2f4}.ttw-facts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1px;border:1px solid #e3eaee;border-radius:10px;background:#e3eaee;overflow:hidden}.ttw-fact{min-height:72px;padding:11px 12px;background:#fff}.ttw-fact dt{color:#71858f;font-size:7px;font-weight:900;letter-spacing:.045em;text-transform:uppercase}.ttw-fact dd{margin:5px 0 0;color:#263f4c;font-size:10px;font-weight:750;line-height:1.45}.ttw-description{margin:0 0 14px;padding:12px 13px;border-left:3px solid #60a2b5;border-radius:0 8px 8px 0;background:#f5f9fa;color:#536b77;font-size:10px;line-height:1.6}.ttw-subhead{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:18px 0 9px}.ttw-subhead h3{margin:0;font-size:12px;font-weight:900}.ttw-subhead span{color:#71858f;font-size:8px}.ttw-docs{display:grid;gap:7px}.ttw-doc{display:grid;grid-template-columns:34px minmax(0,1fr) auto;align-items:center;gap:9px;padding:9px 10px;border:1px solid #dbe5e9;border-radius:9px;color:#284653;text-decoration:none}.ttw-doc:hover{border-color:#7daab7;background:#f8fbfc;color:#176b87}.ttw-doc>i:first-child{display:grid;width:32px;height:32px;place-items:center;border-radius:8px;background:#e8f3f6;color:#176b87}.ttw-doc strong{display:block;font-size:9px}.ttw-doc small{display:block;margin-top:2px;color:#80919a;font-size:7px}.ttw-milestones{display:grid;gap:6px}.ttw-milestone{display:grid;grid-template-columns:minmax(0,1fr) auto auto;align-items:center;gap:10px;padding:8px 10px;border:1px solid #e1e8eb;border-radius:8px;background:#fcfdfd}.ttw-milestone strong{font-size:9px}.ttw-milestone span{color:#6d818c;font-size:8px}.ttw-milestone em{color:#4d6c7b;font-size:8px;font-style:normal;font-weight:800}
    .ttw-control{position:sticky;top:86px;display:grid;gap:12px}.ttw-stage-card{padding:16px;border-radius:13px;background:linear-gradient(145deg,#17384f,#1a6175);color:#fff}.ttw-stage-card small{color:#bee2e8;font-size:8px;font-weight:900;letter-spacing:.06em;text-transform:uppercase}.ttw-stage-card h2{margin:5px 0 7px;color:#fff;font-size:17px;font-weight:900}.ttw-stage-card p{margin:0;color:#d9ebef;font-size:10px;line-height:1.55}.ttw-checklist{display:grid;gap:7px;margin-top:13px}.ttw-check{display:flex;align-items:flex-start;gap:7px;color:#dcebee;font-size:8px}.ttw-check i{margin-top:1px;color:#79d6ae}.ttw-action-box{padding:15px;border:1px solid var(--ttw-line);border-radius:12px;background:#fff}.ttw-action-box h3{display:flex;align-items:center;gap:7px;margin:0 0 5px;font-size:12px;font-weight:900}.ttw-action-box>p{margin:0 0 11px;color:var(--ttw-muted);font-size:9px;line-height:1.5}.ttw-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.ttw-form-stack{display:grid;gap:9px}.ttw-action-row{display:flex;flex-wrap:wrap;gap:7px;margin-top:10px}.ttw-permission-note{display:flex;align-items:flex-start;gap:8px;padding:11px;border:1px solid #e1e7ea;border-radius:9px;background:#f7f9fa;color:#667a84;font-size:9px;line-height:1.5}
    .ttw-source-lock{display:flex;align-items:flex-start;gap:8px;margin-top:8px;padding:9px 11px;border:1px solid #d9e5e9;border-radius:8px;background:#f7fafb;color:#607681;font-size:8px;line-height:1.5}.ttw-source-lock i{margin-top:1px;color:#176b87}.ttw-source-meta{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1px;margin-bottom:9px;border:1px solid #e3eaee;border-radius:9px;overflow:hidden;background:#e3eaee}.ttw-source-meta span{min-width:0;padding:9px 10px;background:#f9fbfc;color:#425d6a;font-size:8px;line-height:1.45;overflow-wrap:anywhere}.ttw-source-meta strong{display:block;margin-bottom:3px;color:#71858f;font-size:7px;letter-spacing:.04em;text-transform:uppercase}.ttw-source-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(235px,1fr));gap:8px}.ttw-source-cell{min-width:0;padding:11px;border:1px solid #dce6ea;border-radius:9px;background:#fcfdfd}.ttw-source-cell header{display:grid;grid-template-columns:auto minmax(0,1fr);align-items:start;gap:8px}.ttw-source-cell header strong{display:inline-flex;padding:3px 6px;border-radius:5px;background:#17384f;color:#fff;font-size:8px}.ttw-source-cell header span{color:#5f7580;font-size:8px;font-weight:850;line-height:1.35;overflow-wrap:anywhere}.ttw-source-value{margin:9px 0;padding:8px;border-left:3px solid #60a2b5;background:#f3f8fa;color:#203f4e;font-size:9px;font-weight:800;line-height:1.45;white-space:pre-wrap;overflow-wrap:anywhere}.ttw-source-cell dl{display:grid;gap:4px;margin:0}.ttw-source-cell dl div{display:grid;grid-template-columns:48px minmax(0,1fr);gap:7px}.ttw-source-cell dt{color:#7a8d97;font-size:7px;font-weight:900;text-transform:uppercase}.ttw-source-cell dd{margin:0;color:#526b77;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:7px;line-height:1.4;white-space:pre-wrap;overflow-wrap:anywhere}.ttw-review-flag{margin-bottom:7px;padding:10px 11px;border:1px solid #efd7af;border-radius:9px;background:#fffaf1}.ttw-review-flag strong{display:block;margin-bottom:6px;color:#79501f;font-size:9px}.ttw-review-flag pre{max-height:280px;margin:0;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;color:#654d32;font-size:7px;line-height:1.45}.ttw-permission-note.evidence-pending{margin-bottom:10px;border-color:#efd7af;background:#fffaf1;color:#79501f}
    .ttw-source-comment{margin-top:9px;padding:8px 9px;border:1px solid #efd7af;border-radius:7px;background:#fffaf1;color:#654d32}.ttw-source-comment strong{display:flex;align-items:center;gap:5px;color:#79501f;font-size:8px}.ttw-source-comment p{margin:5px 0 0;font-size:8px;line-height:1.5;white-space:pre-wrap}.ttw-source-comment small{display:block;margin-top:5px;color:#8a7356;font-size:7px}
    .ttw-timeline{position:relative;display:grid;gap:0}.ttw-event{display:grid;grid-template-columns:30px minmax(0,1fr) auto;gap:10px;padding:0 0 15px}.ttw-event:last-child{padding-bottom:0}.ttw-event-marker{position:relative;z-index:1;display:grid;width:28px;height:28px;place-items:center;border:1px solid #cde0e6;border-radius:50%;background:#edf6f8;color:#1c7189}.ttw-event:not(:last-child) .ttw-event-marker:after{position:absolute;top:28px;bottom:-17px;left:13px;width:1px;background:#d9e5e9;content:""}.ttw-event strong{display:block;margin-top:2px;font-size:9px}.ttw-event p{margin:3px 0 0;color:#6f828c;font-size:8px;line-height:1.45}.ttw-event time{color:#7c8d95;font-size:8px;white-space:nowrap}.ttw-delivery{display:flex;flex-wrap:wrap;gap:5px;margin-top:6px}.ttw-delivery span{display:inline-flex;align-items:center;gap:4px;padding:3px 6px;border-radius:999px;background:#eef3f5;color:#607681;font-size:7px;font-weight:850}.ttw-delivery .sent{background:#e5f5ec;color:#246747}.ttw-delivery .failed{background:#fff0eb;color:#934832}.ttw-review-note{padding:10px 11px;border:1px solid #f0d5b0;border-radius:8px;background:#fff9ef;color:#79501f;font-size:9px;line-height:1.55}
    @media(max-width:1180px){.ttw-metrics{grid-template-columns:repeat(3,1fr)}.ttw-flow{grid-template-columns:repeat(3,1fr);gap:7px}.ttw-flow-step:not(:last-child):after{display:none}.ttw-workspace{grid-template-columns:1fr}.ttw-control{position:static;grid-template-columns:repeat(2,minmax(0,1fr))}.ttw-stage-card{grid-column:1/-1}}
    @media(max-width:860px){.ttw-hero,.ttw-record-hero{grid-template-columns:1fr}.ttw-hero-actions,.ttw-record-actions{justify-content:flex-start}.ttw-filters{grid-template-columns:repeat(2,minmax(0,1fr))}.ttw-facts{grid-template-columns:repeat(2,minmax(0,1fr))}.ttw-source-meta{grid-template-columns:repeat(2,minmax(0,1fr))}}
    @media(max-width:620px){.ttw-metrics{grid-template-columns:repeat(2,1fr)}.ttw-filters,.ttw-form-grid,.ttw-control{grid-template-columns:1fr}.ttw-facts,.ttw-flow,.ttw-source-meta,.ttw-source-grid{grid-template-columns:1fr}.ttw-filter-head,.ttw-panel-head{align-items:flex-start;flex-direction:column}.ttw-filter-actions{justify-content:stretch}.ttw-filter-actions .ttw-btn{flex:1}.ttw-record-actions .ttw-btn,.ttw-hero-actions .ttw-btn{width:100%}.ttw-milestone{grid-template-columns:1fr}.ttw-event{grid-template-columns:30px minmax(0,1fr)}.ttw-event time{grid-column:2}.ttw-hero{padding:22px 19px}}
</style>
@endpush
@endonce
